        seed_rows = [r for r in bar if any(g[r][j] != 0 for j in range(c + 1, w))]
        if seed_rows:
            seed_rows.sort()
            patterns = [[g[r][j] for j in range(c + 1, w)] for r in seed_rows]
            start = bar.index(seed_rows[0])
            for i, r in enumerate(bar):
                pat = patterns[(i - start) % len(patterns)]
                for j, val in enumerate(pat, c + 1):
                    if j < w and g[r][j] == 0:
                        g[r][j] = val

    # Extend patterns attached below horizontal 5-bars.
    for r in range(h):
        bar = [c for c in range(w) if g[r][c] == 5]
        if len(bar) < 2:
            continue
        # Process contiguous horizontal bar segments independently.
        segments = []
        for c in bar:
            if not segments or c > segments[-1][-1] + 1:
                segments.append([c])
            else:
                segments[-1].append(c)
        for seg in segments:
            c0 = seg[0]
            pattern = []
            rr = r + 1
            while rr < h and g[rr][c0] != 0:
                pattern.append(g[rr][c0])
                rr += 1
            if not pattern:
                continue
            for c in seg:
                for k, val in enumerate(pattern, r + 1):
                    if k < h and g[k][c] == 0:
                        g[k][c] = val
    return g
